patch:
diff --git a/repro-19245/eslint.config.js b/repro-19245/eslint.config.js
new file mode 100644
index 0000000..d81c67d
--- /dev/null
+++ b/repro-19245/eslint.config.js
@@ -0,0 +1,7 @@
+module.exports = [
+  {
+    rules: {
+      "no-useless-assignment": "warn"
+    },
+  },
+];
diff --git a/repro-19245/input.js b/repro-19245/input.js
new file mode 100644
index 0000000..f5bbb99
--- /dev/null
+++ b/repro-19245/input.js
@@ -0,0 +1,14 @@
+async function fn() {
+  let intermediaryValue;
+  try {
+    intermediaryValue = 42;
+    unsafeFn();
+    return { error: undefined };
+  } catch {
+    return { intermediaryValue };
+  }
+}
+
+function unsafeFn() {
+  throw new Error();
+}
diff --git a/repro-19245/repro.js b/repro-19245/repro.js
new file mode 100644
index 0000000..994ecf6
--- /dev/null
+++ b/repro-19245/repro.js
@@ -0,0 +1,24 @@
+"use strict";
+// Repro for eslint/eslint#19245: no-useless-assignment false positive in try-catch.
+const fs = require("node:fs");
+const path = require("node:path");
+const assert = require("node:assert");
+const { Linter } = require("../lib/api");
+
+const linter = new Linter();
+const config = { rules: { "no-useless-assignment": "warn" } };
+const run = code => linter.verify(code, config, "input.js");
+
+const reported = fs.readFileSync(path.join(__dirname, "input.js"), "utf8");
+
+// Control: same code without `return` in the try block (per triage comment).
+const control = reported.replace("    return { error: undefined };\n", "");
+
+const r = run(reported);
+const c = run(control);
+console.log("reported code:", JSON.stringify(r.map(m => `${m.line}:${m.column} ${m.message}`)));
+console.log("control (no return in try):", JSON.stringify(c.map(m => `${m.line}:${m.column} ${m.message}`)));
+
+assert.deepStrictEqual(c, [], "control unexpectedly reports");
+assert.deepStrictEqual(r, [], "BUG #19245: `intermediaryValue = 42` flagged although it is read in catch");
+console.log("OK: no false positive");
